package com.prem.order; import io.github.resilience4j.circuitbreaker.CircuitBreaker; import io.github.resilience4j.circuitbreaker.CircuitBreakerRegistry; import io.github.resilience4j.reactor.circuitbreaker.operator.CircuitBreakerOperator; import io.github.resilience4j.reactor.retry.RetryOperator; import io.github.resilience4j.retry.Retry; import io.github.resilience4j.retry.RetryRegistry; import org.springframework.stereotype.Service; import org.springframework.web.reactive.function.client.WebClient; import reactor.core.publisher.Mono; import java.time.Duration; @Service public class ProductClient {private final WebClient.Builder builder;private final CircuitBreaker cb;private final Retry retry;public ProductClient(WebClient.Builder b,CircuitBreakerRegistry c,RetryRegistry r){builder=b;cb=c.circuitBreaker("productService");retry=r.retry("productService");}public Mono<Product> getProduct(Long id){return builder.build().get().uri("http://PRODUCT-SERVICE/products/{id}",id).retrieve().bodyToMono(Product.class).timeout(Duration.ofSeconds(2)).transformDeferred(RetryOperator.of(retry)).transformDeferred(CircuitBreakerOperator.of(cb)).onErrorResume(ex->Mono.just(new Product(id,"Fallback Product",0.0)));}public record Product(Long id,String name,double price){} }
